package app.vpslabs.dashboard;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import java.io.*;import java.net.*;
public class LabsStatusWidget extends AppWidgetProvider{
 @Override public void onEnabled(Context c){WidgetHttp.scheduleAutoRefresh(c);}@Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("app.vpslabs.dashboard.REFRESH_WIDGET".equals(i.getAction())){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID)update(c,AppWidgetManager.getInstance(c),id);}}@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){WidgetHttp.scheduleAutoRefresh(c);for(int id:ids)update(c,m,id);}
 static void update(final Context c,final AppWidgetManager m,final int id){m.updateAppWidget(id,views(c,"Memeriksa…",0xFFd97706,id));new Thread(new Runnable(){public void run(){updateSync(c,m,id);}}).start();}
 static void updateSync(Context c,AppWidgetManager m,int id){String r="Offline";int color=0xFFdc2626;String base=WidgetHttp.base(c);if(base.isEmpty()){r="Belum diatur";color=0xFFd97706;}else try{HttpURLConnection x=(HttpURLConnection)new URL(base+"/health").openConnection();x.setConnectTimeout(8000);x.setReadTimeout(8000);int code=x.getResponseCode();String body=read(code>=200&&code<300?x.getInputStream():x.getErrorStream());if(code==200&&(body.contains("\"ok\":true")||body.contains("true"))){r="Online";color=0xFF16a34a;}else{r="Degraded";color=0xFFd97706;}x.disconnect();}catch(Exception e){r="Offline";}m.updateAppWidget(id,views(c,r+" · "+WidgetHttp.updatedNow(),color,id));}private static RemoteViews views(Context c,String status,int color,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_status);v.setTextViewText(R.id.ws_title,WidgetHttp.brand(c));v.setTextViewText(R.id.ws_status,status);v.setTextColor(R.id.ws_dot,color);v.setOnClickPendingIntent(R.id.ws_root,WidgetHttp.openPage(c,"overview",20));v.setOnClickPendingIntent(R.id.ws_refresh,WidgetHttp.refresh(c,LabsStatusWidget.class,id,2000));return v;}private static String read(InputStream in)throws Exception{if(in==null)return"";BufferedReader b=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);b.close();return s.toString();}}
